/**
 * lib/certificates/brand-mark.ts
 * The Barada symbol mark ("B"), embedded as a base64 PNG data URI for use
 * inside the certificate PDF (lib/certificates/generate-pdf.tsx).
 *
 * Embedded as a literal rather than read from public/logo/ at request time
 * on purpose: this function runs inside the Razorpay webhook's serverless
 * function, and Vercel's file tracing for public/ assets inside API routes
 * is not guaranteed the same way page assets are -- the certificate
 * pipeline has already had one dependency silently fail to resolve in
 * production (pdfkit, Sprint 5), so this avoids adding a second filesystem
 * dependency to the same code path. Source file:
 * public/logo/barada-symbol-512.png (512x512, transparent background).
 */
export const BARADA_SYMBOL_MARK_PNG_DATA_URI =
  'data:image/png;base64,'
